/bin/bash -c 'if [ -z "$SYNC_DEST" ]; then sleep infinity; fi; INTERVAL_MIN=$(echo "${SYNC_INTERVAL:-5}" | tr -dc "0-9"); [ -z "$INTERVAL_MIN" ] && INTERVAL_MIN=5; INTERVAL_SEC=$((INTERVAL_MIN * 60)); MASKED_DEST=$(echo "$SYNC_DEST" | sed -E -e "s/(:\/\/[^:]+:)[^@]+@/\1***@/g" -e "s/(secret_access_key|access_key_id|password|pass|token|client_secret)=([^,:]+)/\1=\"***\"/g"); echo "[AutoSync] 每 ${INTERVAL_MIN} 分钟自动同步至 $MASKED_DEST"; sync_data() { echo "[AutoSync] === 同步开始于 $(date +'%Y-%m-%d %H:%M:%S') ==="; START=$(date +%s); echo "dummy sync"; END=$(date +%s); echo "[AutoSync] === 同步完成于 $(date +'%Y-%m-%d %H:%M:%S') (耗时: $((END - START))秒) ==="; }; trap "echo \"[AutoSync] 收到关机指令，正在执行最后一次强制备份...\"; sync_data; exit 0" SIGTERM SIGINT; sync_data; exit 0'
